#[test]
fn test_every_row_of_the_filter_corpus() {
    let f: &[u8] = &crate::testport::test_file("pdf/filters.txt")[..];
    let inp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n: i32 = crate::port::blob_len(f);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut rows: i32 = 0;
    let mut e: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut s3: i32 = 0;
    let mut s4: i32 = 0;
    let mut s5: i32 = 0;
    let mut status: i32 = 0;
    while pos < n {
        line += 1;
        e = ft_nl(f, pos);
        if (pos < e) && (crate::port::blob_u8(f, pos) != 35) {
            rows += 1;
            s1 = ft_tab(f, pos, e);
            s2 = ft_tab(f, s1 + 1, e);
            s3 = ft_tab(f, s2 + 1, e);
            s4 = ft_tab(f, s3 + 1, e);
            s5 = ft_tab(f, s4 + 1, e);
            status = ft_run(f, s1, s2, s3, s4, inp, out, tmp, st);
            let t: &mut String = &mut crate::port::new_text();
            pf_status_emit_name(t, status);
            crate::testport::assert_text_span(t, f, s4 + 1, s5, "status", line);
            crate::testport::assert_eq_at(ft_compare(out, f, s5 + 1, e), -1, "output", line);
        }
        pos = e + 1;
    }
    crate::testport::assert_that(rows > 60, "the corpus was read");
}
